import pyomo.environ as pyo

DATA = {
    "piece_lengths": [3, 4],
    "stock_length": 10,
    "demand": {3: 90, 4: 60},
    "patterns": [
        (3, 0),   # 3 pieces of 3 m
        (2, 1),   # 2 pieces of 3 m, 1 piece of 4 m
        (0, 2),   # 2 pieces of 4 m
    ],
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.P = pyo.RangeSet(0, len(d["patterns"]) - 1)
    model.L = pyo.Set(initialize=d["piece_lengths"])

    # contribution of pattern p to length L
    pattern_contrib = {
        (p, L): d["patterns"][p][i]
        for p in range(len(d["patterns"]))
        for i, L in enumerate(d["piece_lengths"])
    }

    total_demand = sum(d["demand"][L] for L in d["piece_lengths"])

    def _ub(m, p):
        return total_demand

    model.x = pyo.Var(model.P, domain=pyo.NonNegativeIntegers,
                      bounds=(0, _ub))

    # Objective: minimise the total number of 10 m stock bars used
    model.obj = pyo.Objective(
        expr=sum(model.x[p] for p in model.P),
        sense=pyo.minimize,
    )

    # Demand constraints: exact demand satisfaction for each length
    def demand_rule(m, L):
        return sum(m.x[p] * pattern_contrib[(p, L)] for p in m.P) == d["demand"][L]

    model.demand_con = pyo.Constraint(model.L, rule=demand_rule)

    # Feasibility sanity constraint: total produced stock length must be >= total demand length
    def length_feasibility_rule(m):
        return sum(m.x[p] * d["stock_length"] for p in m.P) >= sum(
            d["demand"][L] * L for L in d["piece_lengths"]
        )

    model.length_feasibility = pyo.Constraint(rule=length_feasibility_rule)

    # Pattern validity: each pattern must not exceed stock length
    def pattern_validity_rule(m, p):
        return sum(
            d["patterns"][p][i] * d["piece_lengths"][i]
            for i in range(len(d["piece_lengths"]))
        ) <= d["stock_length"]

    model.pattern_validity = pyo.Constraint(model.P, rule=pattern_validity_rule)

    return model


